<?php
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/layout.php';$user=require_login();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$initialAgent=filter_input(INPUT_GET,'agent',FILTER_VALIDATE_INT);$team=null;
try{$repo=new BusinessRepository(db());$agents=$repo->catalogue();if($id)$team=$repo->configuration($id,(int)$user['id']);}catch(PDOException $error){error_log($error->getMessage());render_database_unavailable();}
if(isset($_GET['id']) && !$team)render_not_found();
$plan=is_string($_GET['plan'] ?? null) && isset(plan_definitions()[$_GET['plan']])?$_GET['plan']:'business';
$old=$_SESSION['configuration_old'] ?? [];unset($_SESSION['configuration_old']);
$values=array_merge(['name'=>'','objective'=>'','sector'=>'otro','plan'=>$plan],$team ?? [],array_filter($old,'is_string'));
if(!isset(plan_definitions()[$values['plan']]))$values['plan']='business';
$selected=$team?array_map('intval',array_column($team['agents'],'id')):($initialAgent?[$initialAgent]:[]);
if(isset($old['agents']) && is_array($old['agents']))$selected=array_map('intval',$old['agents']);
$available=array_map('intval',array_column($agents,'id'));$selected=array_values(array_unique(array_intersect($selected,$available)));
render_header($team?'Editar equipo':'Diseña tu equipo');
?>
<section class="page-heading"><a class="back-link" href="<?= e(url('dashboard.php')) ?>">← Mi espacio de empresa</a><p class="eyebrow">DISEÑA ALREDEDOR DE UN OBJETIVO</p><h1><?= $team?'Tu equipo puede evolucionar.':'Distintos agentes. Un mismo propósito.' ?></h1><p>Elige especialistas, establece su orden y guarda una configuración para tu empresa. Después podrás solicitar una propuesta.</p></section>
<form id="team-form" class="builder-layout" action="<?= e(url('actions.php')) ?>" method="post" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="configuration_save"><input type="hidden" name="configuration_id" value="<?= (int)$id ?>"><div><section class="panel stack-form"><h2>01. Define el objetivo</h2><label class="field"><span>Nombre del equipo</span><input name="name" minlength="3" maxlength="100" value="<?= e($values['name']) ?>" placeholder="Ej. Campaña de lanzamiento" required></label><label class="field"><span>¿Qué necesitas conseguir?</span><textarea name="objective" minlength="20" maxlength="2000" rows="4" placeholder="Describe el resultado esperado y qué información tendrá el equipo." required data-count><?= e($values['objective']) ?></textarea></label><div class="form-row"><label class="field"><span>Sector</span><select name="sector"><?php foreach(sector_labels() as $key=>$label): ?><option value="<?= e($key) ?>" <?= $values['sector']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label class="field"><span>Plan de referencia</span><select name="plan" id="team-plan"><?php foreach(plan_definitions() as $key=>$definition): ?><option value="<?= e($key) ?>" data-limit="<?= $definition['limit'] ?>" <?= $values['plan']===$key?'selected':'' ?>><?= e($definition['name'].' · '.$definition['price']) ?></option><?php endforeach; ?></select></label></div><p class="field-help">Precios orientativos de la propuesta académica. Elegir un plan no activa una suscripción ni realiza un cobro.</p></section><section class="team-catalogue"><div class="section-heading"><h2>02. Elige tus agentes</h2></div><div class="selection-grid"><?php foreach($agents as $agent): ?><label class="select-agent-card panel"><div class="card-top"><?php agent_visual($agent['icon'],$agent['color']); ?><input type="checkbox" class="agent-pick" value="<?= (int)$agent['id'] ?>" aria-label="Añadir <?= e($agent['name']) ?>" <?= in_array((int)$agent['id'],$selected,true)?'checked':'' ?>></div><h3><?= e($agent['name']) ?></h3><p><?= e($agent['summary']) ?></p><span class="pill"><?= e(category_labels()[$agent['category']]) ?></span></label><?php endforeach; ?></div></section></div><aside class="panel team-summary"><p class="eyebrow">03. COMBINA SUS FUNCIONES</p><h2>Tu secuencia de trabajo.</h2><p class="field-help">El orden explica cómo se complementarán. Puedes mover o quitar agentes.</p><ol class="selected-list" id="selected-list"><?php foreach($selected as $agentId): $item=$agents[array_search($agentId,$available,true)]; ?><li><?= e($item['name']) ?></li><?php endforeach; ?></ol><div id="selected-inputs"><?php foreach($selected as $agentId): ?><input type="hidden" name="agents[]" value="<?= $agentId ?>"><?php endforeach; ?></div><p id="selection-status" class="selection-status" role="status">Elige al menos un agente.</p><button class="button" id="save-team" type="submit">Guardar equipo ↗</button><?php if($team): ?><a class="button outline" href="<?= e(url('request.php?configuration='.$id)) ?>">Solicitar propuesta ↗</a><?php endif; ?><p class="field-help">Se guarda tu selección; no se ejecuta el flujo ni se transmiten datos a servicios externos.</p><noscript><p>Activa JavaScript para seleccionar y ordenar los agentes.</p></noscript></aside></form>
<?php if($team): ?><details class="danger-zone"><summary>Eliminar este equipo</summary><p>Se eliminará la configuración. Las solicitudes ya registradas conservarán sus datos.</p><form action="<?= e(url('actions.php')) ?>" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="configuration_delete"><input type="hidden" name="configuration_id" value="<?= (int)$id ?>"><label class="field"><span>Escribe ELIMINAR para confirmar</span><input name="confirmation" required pattern="ELIMINAR" autocomplete="off"></label><button class="button danger" type="submit">Eliminar equipo</button></form></details><?php endif; ?>
<script type="application/json" id="builder-data"><?= json_encode(['agents'=>array_map(fn($item)=>['id'=>(int)$item['id'],'name'=>$item['name']],$agents),'selected'=>$selected],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE) ?></script><script src="<?= e(asset_url('assets/js/builder.js')) ?>" defer></script>
<?php render_footer(); ?>
